  const out={schema:2};
  for(const[k,v]of Object.entries(s)){
    if(k==="schema")continue;
    if(k==="retries")continue;
    out[k]=v;
  }
  // insert retryCount at old retries position: simplest rebuild preserving order
  const out2={schema:2};
  for(const[k,v]of Object.entries(s)){
